use super::*;
fn fixture(kind:&str)->(std::path::PathBuf,Json){let dir=super::super::lifecycle_tests::root();fs::create_dir_all(&dir).unwrap();let mut trials=vec![];let mut pack=vec![];let mut keys=vec![];let mut rs=vec![];
 let conditions=if kind=="life"{vec!["full","replica","probe_no_recon","no_sleep","no_recon","rag","empty"]}else if kind=="preview"{vec!["empty","rag","before_sleep","after_no_recon","after_full"]}else{vec!["empty","rag","selmem_no_recon","selmem_full"]};
 for history in ["one","two"]{for task in ["a","b","c"]{for c in &conditions{for repeat in 0..2{let id=format!("C{}",trials.len());let trial_id=format!("{history}/{task}/{c}/{repeat}");let mut t=obj([("trial_id",text(&trial_id)),("history",text(history)),("task",obj([("id",text(task))])),("condition",text(*c)),("repeat",num(repeat as f64)),("generation",obj([("valid",Json::Bool(true))]))]);if kind=="life"{t.put("pair",text("pair"));t.put("branch",text(if history=="one"{"a"}else{"b"}));t.put("day",num(120.));t.put("phase",text("primary"));}trials.push(t);pack.push(obj([("id",text(&id)),("proposal",text("idea")),("problem",text("problem"))]));keys.push(obj([("id",text(&id)),("trial_id",text(trial_id))]));for rater in ["judge-a","judge-b"]{rs.push(obj([("id",text(&id)),("rater",text(rater)),("utility",num(3.)),("originality",num(4.)),("constraints_met",Json::Bool(true)),("rationale",text("Concrete useful mechanism."))]));}}}}}
 write(&dir.join(if kind=="life"{"life.json"}else if kind=="preview"{"preview.json"}else{"creative.json"}),&obj([("status",text("technical_rehearsal_complete")),("mock",Json::Bool(true)),("planned_proposals",num(trials.len() as f64)),("completed_proposals",num(trials.len() as f64))])).unwrap();write(&dir.join("all-proposals.json"),&arr(trials.clone())).unwrap();fs::write(dir.join("creative-proposals.jsonl"),trials.iter().map(|t|format!("{}\n",t.encode())).collect::<String>()).unwrap();write(&dir.join("blind-proposals.json"),&arr(pack)).unwrap();write(&dir.join("private-blind-key.json"),&arr(keys)).unwrap();(dir,arr(rs))}
#[test]fn rejects_unpinned_source(){assert!(prepare::build("prepare-preview","",b"[]").is_err());}
#[test]fn preview_blind_coverage_invalid_generations_and_rater_guards(){let (dir,rs)=fixture("preview");let report=ratings::analyze(&dir,&rs,"preview").unwrap();assert_eq!(n(&report,"proposals").unwrap(),60.);assert!(array(&report,"scored").unwrap().iter().all(|r|n(r,"creative_score").unwrap()==3.));let mut missing=rs.array().unwrap().to_vec();missing.remove(0);assert!(ratings::analyze(&dir,&arr(missing),"preview").is_err());let mut duplicate=rs.array().unwrap().to_vec();duplicate.push(duplicate[0].clone());assert!(ratings::analyze(&dir,&arr(duplicate),"preview").is_err());let mut trials=load(&dir.join("all-proposals.json")).unwrap().array().unwrap().to_vec();trials[0].put("generation",obj([("valid",Json::Bool(false))]));write(&dir.join("all-proposals.json"),&arr(trials)).unwrap();assert_eq!(n(&array(&ratings::analyze(&dir,&rs,"preview").unwrap(),"scored").unwrap()[0],"creative_score").unwrap(),0.);fs::remove_dir_all(dir).unwrap();}
#[test]fn life_and_historical_creative_formats_remain_readable(){for kind in ["life","creative"]{let (dir,rs)=fixture(kind);let report=ratings::analyze(&dir,&rs,kind).unwrap();if kind=="life"{assert_eq!(array(&report,"pairContrasts").unwrap().len(),1);assert!(array(&report,"pairContrasts").unwrap()[0].get("full_minus").unwrap().object().unwrap().values().all(|v|v.number().unwrap()==0.));}else{assert_eq!(n(&report,"histories").unwrap(),2.);}fs::remove_dir_all(dir).unwrap();}}
#[test]fn mechanism_consensus_distances_and_missing_coders(){let (dir,_)=fixture("life");let pack=load(&dir.join("blind-proposals.json")).unwrap();let coding=arr(pack.array().unwrap().iter().flat_map(|p|["one","two"].map(|rater|obj([("id",p.get("id").unwrap().clone()),("rater",text(rater)),("mechanism_summary",text("Iterative peer feedback.")),("tags",arr([text("iteration")]))]))));let report=mechanisms::analyze(&dir,&coding).unwrap();assert_eq!(n(&report,"independent_pairs").unwrap(),1.);assert!(array(&report,"contrasts").unwrap().iter().all(|r|n(r.get("developmental_same_history").unwrap(),"a").unwrap()==0.));let missing=arr(coding.array().unwrap().iter().skip(1).cloned());assert!(mechanisms::analyze(&dir,&missing).is_err());fs::remove_dir_all(dir).unwrap();}
#[test]fn utility_and_constraints_gate_originality_without_substitution(){let (dir,rs)=fixture("preview");let mut rs=rs.array().unwrap().to_vec();for r in &mut rs{r.put("utility",num(0.));}assert!(array(&ratings::analyze(&dir,&arr(rs.clone()),"preview").unwrap(),"scored").unwrap().iter().all(|r|n(r,"creative_score").unwrap()==0.));for r in &mut rs{r.put("utility",num(4.));r.put("constraints_met",Json::Bool(false));}assert!(array(&ratings::analyze(&dir,&arr(rs),"preview").unwrap(),"scored").unwrap().iter().all(|r|n(r,"creative_score").unwrap()==0.));fs::remove_dir_all(dir).unwrap();}
#[test]fn fresh_outputs_never_overwrite_existing_work(){let dir=super::super::lifecycle_tests::root();fs::create_dir_all(&dir).unwrap();let path=dir.join("ratings.json");fresh(&path,&arr([])).unwrap();let before=file_hash(&path).unwrap();assert!(fresh(&path,&text("replacement")).is_err());assert_eq!(file_hash(&path).unwrap(),before);fs::remove_dir_all(dir).unwrap();}
